import argparse,datetime,hashlib,json # Freeze the user-directed complex-physics campaign and exact evidence identities.
from pathlib import Path # Resolve campaign evidence relative to the checked-out repository.
REPO=Path(__file__).resolve().parents[2] # Keep runtime paths portable within the existing repository.
OUT=REPO/'build/complex-nonlinear-20261024' # Preserve the previous reduced experiments as separate historical evidence.
def sha(path): # Hash actual source and result bytes without inferring identity from names.
    return hashlib.sha256(Path(path).read_bytes()).hexdigest() # Return a reproducible SHA-256 fingerprint.
def write(path,value): # Write reviewable metadata without overwriting an earlier contract silently.
    path.parent.mkdir(parents=True,exist_ok=True);path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n') # Preserve human-readable Unicode metadata.
def contract(): # Declare the experiment before inspecting new independent test performance.
    value={'schema':'bridge.complex.fullfield.campaign.v1','created_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_md':'bridge_group_three_module_autoregressive_design.md','source_md_sha256':'4d94495ca84c7161dc5b74a975f2513c68407691ef0291cd5b79adedfb42b7b7','user_change':'Focus on genuinely nonlinear local mechanisms; define negative examples as surrogate-reference discrepancies; remove fixed POD/modal response truncation.'} # Anchor the scientific objective in the exact source and user correction.
    value['negative_definition']={'reference_requirement':'Native converged FEM result with explicit quality evidence; failed or corrupt solves are never response truth.','unit':'same physical history, same field location, same time and same model/reference version','classification':'a field error above a predeclared research threshold','retained_evidence':['neural_prediction','native_reference','error_map','field_location','time','input_parameters','load_history','checkpoint_hash','reference_hash'],'not_equivalent_to':['structural_failure','solver_nonconvergence','out_of_domain_flag']} # Distinguish hard response examples from unrelated failure categories.
    value['representation']={'fixed_POD_response_basis':False,'modal_truncation':False,'coarsened_prediction_graph':False,'polynomial_response_lifting':False,'physical_entities':'All source FE nodes, exported material integration points and persistent contact/interface entities supported by each documented dataset.','history':'Known initial state followed by free neural rollout; plastic tensor/internal variables or explicit observation-state limitation; no test-teacher-forcing.'} # Freeze the representation restrictions that remove the earlier artificial output subspace.
    value['physics_branches']={'thermoplastic':'Transient thermal field and cyclic elastic-plastic material response with recorded coupling direction.','friction':'Normal contact, stick/slip, pressure modulation, reversal and separation/recontact when verified.','rebar':'Explicit steel reinforcement plasticity and nonlinear interface force-transfer law; concrete cracking is claimed only if actually implemented and verified.'} # Name physical mechanisms without claiming unimplemented damage or phase-field models.
    value['sampling']={'initial_requested_per_branch':{'train':8,'validation':3,'test':4,'ood':4},'candidate_descriptors_per_branch':16,'active_rounds':2,'native_cases_per_active_round':2,'random_acquisition_comparator_cases':4,'split_unit':'whole history parameter group','test_role':'Frozen final comparison only; never acquisition, fit, hyperparameter selection or error-model fitting.','acquisition_goal':'Find histories expected to yield large surrogate-reference discrepancies and information gain per native calculation cost.'} # Separate actual FEM acquisitions from inexpensive candidate scoring.
    value['research_error_thresholds']={'displacement_relative_L2':0.05,'stress_relative_L2':0.10,'plastic_state_relative_L2':0.15,'denominator_floor':'Training-only field scale with explicit frozen implementation metadata; zero-reference cases reported separately.','engineering_acceptance':False} # Freeze diagnostic research thresholds before seeing final test outcomes.
    value['required_checks']=['exact_input_output_identity','complete_field_coverage','history_group_split_disjointness','known_initial_only_rollout','all_source_entity_prediction_coverage','training_only_normalization','native_physics_checks','representative_mesh_and_step_refinement','checkpoint_reload','node_permutation','equal_budget_random_acquisition_comparison','failed_attempt_retention'] # Make the evidence required for each later claim explicit.
    value['phase_field_status']='NOT_IMPLEMENTED_BY_THIS_CONTRACT; never add a name without a verified evolution equation, irreversibility law, length-scale study and real solved fields.' # Keep crack phase-field development distinct from available plastic and interface physics.
    path=OUT/'campaign_contract.json' # Preserve the frozen design separately from changing progress records.
    if path.exists(): return json.loads(path.read_text()) # Reuse the initial registered contract rather than rewriting its timestamp.
    write(path,value);return value # Store the pre-test contract once.
def inventory(): # Collect only files that actually exist without claiming unfinished training or native solves.
    rows=[] # Track exact file-backed progress for each physical branch.
    for name in ['thermoplastic','friction','rebar','learning','audit']: # Keep branch ownership independent for concurrent producers.
        directory=OUT/name;files=list(directory.rglob('*')) if directory.exists() else [];files=[p for p in files if p.is_file() and '__pycache__' not in p.parts];rows.append({'branch':name,'files':len(files),'bytes':sum(p.stat().st_size for p in files),'json_files':[str(p.relative_to(OUT)) for p in files if p.suffix=='.json']}) # Report only current facts and locations.
    return {'schema':'bridge.complex.progress.v1','observed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'contract_sha256':sha(OUT/'campaign_contract.json'),'branches':rows} # Tie evolving evidence to the unchanged registered objective.
if __name__=='__main__': # Expose deterministic contract creation and read-only evidence inventory.
    parser=argparse.ArgumentParser();parser.add_argument('action',choices=['contract','inventory']);args=parser.parse_args();contract();result=contract() if args.action=='contract' else inventory();print(json.dumps(result,ensure_ascii=False,indent=2)) # Print concrete current evidence, never synthetic completion status.
